import os, sys, math

def modular_power(a, n, m):
	if n == 0:
		return 1
	a = a % m
	if a < 0:
		a += m
	prod = 1
	pwr = a
	while n != 0:
		if n % 2 != 0:
			prod = prod * pwr % m
		n >>= 1
		if n == 0:
			break
		pwr = pwr * pwr % m
	return prod
MOD_INVERSE_CACHE = {}

def modular_inverse_cached(a, m):
	y = MOD_INVERSE_CACHE.get(m, {}).get(a)
	if y is None:
		y = modular_inverse(a, m)
		if m not in MOD_INVERSE_CACHE:
			MOD_INVERSE_CACHE[m] = {}
		MOD_INVERSE_CACHE[m][a] = y
	return y

def modular_inverse(a, m):
	m0 = m
	y = 0
	x = 1
	if m == 1:
		return 0
	while a > 1:
		q = a // m
		t = m
		m = a % m
		a = t
		t = y
		y = x - q * y
		x = t
	if x < 0:
		x = x + m0
	return x

def solve1_basic(nmax, kmax):
	modulus = 10 ** 9 + 7
	A = [0] * (kmax + 1)
	A[0] = kmax - 1
	A[1] = 1
	for n in range(2, nmax + 1):
		t = A[0]
		A[0] = A[0] * (kmax - 1) % modulus
		for k in range(1, min(n, kmax) + 1):
			c = max(k, kmax - 1)
			(t, A[k]) = (A[k], (c * A[k] + t) % modulus)
	return A[kmax]

def solve1(n, a):
	modulus = 10 ** 9 + 7
	f = (a - 1) * modular_inverse_cached(a, modulus) % modulus
	t = 1
	s = 1
	for k in range(a, n):
		t = t * k * f * modular_inverse_cached(k - a + 1, modulus) % modulus
		s = (s + t) % modulus
	s = modular_power(f, a - 1, modulus) * s % modulus
	a1inv = modular_inverse_cached(a - 1, modulus)
	return modular_power(a, n - 1, modulus) * modular_power(a1inv, a - 1, modulus) * s % modulus

def solve(cases):
	for (n, k) in cases:
		print(solve1(n, k))

